import React from 'react';
import {useDraft} from '../../shared/state.js';
import {SaveBar,saveShortcut} from '../../shared/ui.jsx';
import {DocumentTextarea} from '../../shared/workspace.tsx';
import {useDialog} from '../../dialog.tsx';
import {useWritingRequest} from '../../shared/writing-request.js';
import {relationKinds,relationStyles} from '../structure/Timeline.jsx';
export function EdgeEditor({call,novelId,nodes,run,busy,initial,saved}) {
 const {value:draft,base,change,accept,dirty,cacheError}=useDraft(`${novelId}:edge:${initial.id||`new:${initial.from}:${initial.to}`}`,initial),write=useWritingRequest(call),{confirm}=useDialog();
 const set=(key,value)=>change(d=>({...d,[key]:value}));
 const save=()=>{if(draft.from&&draft.to&&!busy)run(async()=>{const e=await write(draft.id?'edge.update':'edge.create',{from:draft.from,to:draft.to,name:draft.name,content:draft.content,category:draft.category||'other',style:draft.style||'solid',baseActive:draft.baseActive!==false,timing:draft.timing||'base',novelId,edgeId:draft.id,expectedRevision:base.revision});accept(e);saved(e);});};
 return <div onKeyDown={e=>saveShortcut(e,save)}><fieldset disabled={busy} className="editor-fields">{[['from','从'],['to','到']].map(([key,label])=><label key={key}>{label}<select value={draft[key]} onChange={e=>set(key,e.target.value)}>{nodes.map(n=><option key={n.id} value={n.id}>{n.name}</option>)}</select></label>)}<label>关系名称（可选）<input placeholder="例如：居住于、朋友、敌对" value={draft.name||''} onChange={e=>set('name',e.target.value)}/></label><label>类别<select aria-label="基础关系类别" value={draft.category||'other'} onChange={e=>set('category',e.target.value)}>{Object.entries(relationKinds).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label><label>线型<select aria-label="基础关系线型" value={draft.style||'solid'} onChange={e=>set('style',e.target.value)}>{Object.entries(relationStyles).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label><label>故事开始前<select aria-label="基础关系是否存在" value={draft.baseActive!==false?'base':draft.timing||'undated'} onChange={e=>change(d=>({...d,baseActive:e.target.value==='base',timing:e.target.value}))}><option value="base">已存在</option><option value="event">不存在，由具体事件决定</option><option value="undated">时间未定</option></select></label><label>说明<DocumentTextarea value={draft.content||''} onChange={e=>set('content',e.target.value)}/></label></fieldset><SaveBar dirty={dirty||!draft.id} {...{busy}} error={cacheError} invalid={!draft.from||!draft.to?'请选择关系端点':null} onSave={save} label="保存关系"/>{draft.id&&<details><summary>更多操作</summary><button disabled={busy} onClick={async()=>{if(!dirty||await confirm('丢弃关系草稿并读取最新版本？'))run(async()=>{const latest=await call('edge.get',{novelId,edgeId:draft.id});accept(latest);saved(latest);});}}>读取最新关系</button><button disabled={busy} className="danger" onClick={async()=>{if(await confirm('删除这条关系？'))run(async()=>{await write('edge.delete',{novelId,edgeId:draft.id,expectedRevision:base.revision,confirm:true});accept(initial);saved(null);});}}>删除关系</button></details>}</div>;
}
